// Antoine: log10(P_mmHg) = A - B/(C + T°C)
struct DatosEspecie {
    const char* nombre;
    const char* formula;
    double M, Hf, Sf, Cp_a, Cp_b, Cp_c, Cp_d;
    double AntA, AntB, AntC, AntTmin, AntTmax;
    int fase_std; // 0=gas, 1=líquido, 2=sólido
};

